const pending=new Map();
function notice(message){const n=$("notice");n.textContent=message;n.hidden=!message;if(message){try{if(n.style)n.style.scrollMarginTop="90px";if(n.scrollIntoView)n.scrollIntoView({block:"start",behavior:"smooth"});}catch(e){}}}
function lock(value,modal=true){busy=value;if(!modal)return;document.querySelectorAll("button,input,select,textarea").forEach(e=>e.disabled=value);if(value&&modal)$("sync-dialog").showModal();else if(!value)$("sync-dialog").close();}
$("sync-dialog").addEventListener("cancel",event=>{if(busy)event.preventDefault();});
window.urb4nReceive=(id,json)=>{const job=pending.get(id);if(!job)return;pending.delete(id);try{job.resolve(JSON.parse(json));}catch(e){job.reject(Error("Réponse de synchronisation invalide"));}};
async function api(command,args={}){
 if(busy)return;
 if(demo && command==="fuel"){const pellet=args.fuel==="pellets";state.fuel=args.fuel;state.fuels=pellet?["Pellets de bois","Badger Pellets","Woodies"]:["Anthracite","Charbon mixte"];state.calibres=pellet?["6 mm","8 mm"]:["15/25","10/20"];state.data={view:{Valid:true,Stock:pellet?90:180,Daily:pellet?6:8.5},bag_kg:pellet?15:25,bucket_empty_kg:1.2,bucket_full_kg:8.2,purchases:[]};state.reloads=[{date:new Date().toLocaleDateString("fr-BE"),hour:"08:30",fuel:pellet?"Badger Pellets":"Anthracite",calibre:pellet?"6 mm":"15/25",kg:pellet?15:7,duration:"En cours · 1 h 30 min",cost:pellet?5.4:3.68}];state.days=pellet?15:21;state.dailyCost=pellet?2.16:4.46;render();return;}
 if(demo && !["snapshot","disconnect"].includes(command)){notice("Mode démonstration : aucune donnée n’est envoyée. Connecte-toi pour utiliser ton vrai suivi.");return;}
 if(!window.Urb4nNative){if(command==="connect"){notice("Ceci est un aperçu dans le navigateur. La connexion Google fonctionne dans l’application Android après configuration du client Google.");return;}if(command==="disconnect"){demo=false;state.connected=false;render();return;}if(command==="fuel"){state.fuel=args.fuel;render();return;}if(command==="snapshot")return;}
 const id=String(++sequence);lock(true,!["snapshot","fuel","bugsMine","ticketThread","ticketSay","adminList","adminDetail","announcement","adminCtlOverview","weather"].includes(command));if(command!=="adminCtlOverview"&&command!=="weather")notice("");
 try{
  const result=await new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});window.Urb4nNative.request(id,command,JSON.stringify(args));});
  if(result.app_version){installedVersion=result.app_version;if($("app-version"))$("app-version").textContent="Web · "+installedVersion.replace(/-beta\.?/," bêta ").replace(/^(\d+\.\d+)\.0$/,"$1").trim();}
  if(command.startsWith("update")){if(result.ok&&command==="updateCheck")updateInfo=result;if(command==="updateTest"){render();notice(result.sent?"Notification de test envoyée : regarde en haut de l’écran.":"Les notifications sont bloquées : active-les avec le bouton ci-dessus.");return result;}if(command==="updateBattery"){render();notice(result.battery?"C’est déjà bon : URB4N APP n’est pas limitée en arrière-plan.":"Choisis « Autoriser » dans la fenêtre Android, puis reviens ici.");return result;}if(command==="updateNotif"){render();notice("Active les notifications pour URB4N APP dans la fenêtre Android, puis reviens ici.");return result;}render();notice(result.ok?(command==="updateNotif"?"Active les notifications pour URB4N APP dans la fenêtre Android, puis reviens ici.":command==="updateInstall"?"Valide l’installation dans la fenêtre Android.":result.update_available?"Une nouvelle version est disponible.":"Tu utilises la version la plus récente de ce canal."):result.error||"Mise à jour indisponible");return result;}
  if(command==="weather"){weatherBusy=false;if(result.ok&&result.weather){weatherInfo=result.weather;weatherAt=Date.now();try{localStorage.setItem("urb4n.wx",JSON.stringify({at:weatherAt,city:cityName(),info:weatherInfo}));}catch(e){}try{localStorage.setItem("urb4n.geo",JSON.stringify({typed:cityName(),lat:result.weather.lat,lon:result.weather.lon,name:result.weather.city}));}catch(e){}render();if(args.manual==="1")notice("Météo mise à jour pour "+result.weather.city+".");}else if(args.manual==="1"){notice(result.error||"Météo indisponible.");}return result;}
  if(command==="announcement"){if(result.ok){annLive=result.announcement||null;try{if(annLive)localStorage.setItem("urb4n.ann",JSON.stringify(annLive));else localStorage.removeItem("urb4n.ann");}catch(e){}}renderAnnouncement();return result;}
  if(command.startsWith("adminCtl")){
   if(result.ok){
    if(result.ctl)ctl=result.ctl;if(command==="adminCtlOverview"){ctlAt=new Date();ctlDown=false;}
    if(command==="adminCtlExport"){ctlCsv=result.csv||"";ctlCsvName=result.filename||"export.csv";notice("Export prêt : copie le texte ci-dessous.");}
    else if(command!=="adminCtlOverview")notice({adminCtlSuspend:"Statut du compte mis à jour.",adminCtlRole:"Rôle du compte mis à jour.",adminCtlDelete:"Compte supprimé.",adminCtlAnnounce:args.starts?"Annonce programmée.":"Annonce publiée.",adminCtlClear:"Annonce retirée."}[command]||"Fait.");
   }else{if(command==="adminCtlOverview")ctlDown=true;else notice(result.error||"Administration indisponible.");}
   render();
   if(result.ok&&["adminCtlSuspend","adminCtlRole","adminCtlDelete","adminCtlAnnounce","adminCtlClear"].includes(command)){Promise.resolve().then(async()=>{await api("adminCtlOverview");await api("announcement");});}
   return result;
  }
  if(command.startsWith("admin")){
   if(result.ok){if(command==="adminList")adminTickets=result.admin_tickets||[];adminLoaded=true;if(result.admin_ticket)adminThreads[result.admin_ticket.id]=result.admin_ticket;if(command==="adminDelete"){adminOpen="";}
    if(command==="adminStatus")notice("Statut et réponse enregistrés.");if(command==="adminTitle")notice("Titre modifié.");if(command==="adminNote")notice("Note enregistrée.");if(command==="adminDelete")notice("Signalement supprimé.");}
   else notice(result.error||"Boîte des bugs indisponible.");
   render();
   if(result.ok&&["adminStatus","adminDelete","adminTitle","adminNote"].includes(command))api("adminList");
   return result;
  }
  if(command.startsWith("registry")){
   registry.choice=result.registry_choice??registry.choice;registry.admin=result.registry_admin??registry.admin;registry.name=result.user_name??registry.name;if(command==="registryRole"&&result.ok)registry.role=result.role||"user";registry.donor=!!result.donor;registry.email=result.email||registry.email;if(!registry.admin){registry.users=[];registry.entries=[];registry.total=0;}
   if(result.users){registry.users=result.users;registry.entries=result.entries||[];registry.total=result.total||0;}
   if(command==="registryName"&&result.ok)dirty=false;
   if(command==="registryName"&&result.ok)notice(registry.name?"Nom enregistré : "+registry.name:"Nom effacé du registre.");
   if(command==="registryRole"&&result.ok&&!args.auto)notice(registry.admin?"Accès administrateur reconnu.":"Ce compte n’est pas administrateur du registre.");
   
   if(command==="registryRegister"&&result.ok&&result.registered&&registry.choice==="registered"&&state.connected){page="dashboard";dirty=false;closeMenu();window.scrollTo(0,0);notice("Ton compte est prêt.");}
   if(command==="registryWithdraw"&&result.ok)notice("Inscription supprimée. Le suivi est verrouillé jusqu’à une nouvelle inscription.");
   if(!result.ok)notice(result.error||"Inscription indisponible. Réessaie pour accéder au suivi.");
   render();return result;
  }
  if(result.data){if(command==="disconnect"&&result.ok){registry={choice:"",admin:false,role:"",donor:false,email:"",users:[],entries:[],total:0,name:""};tickets=[];ticketsLoaded=false;adminTickets=[];adminLoaded=false;adminThreads={};threads={};ticketOpen="";ticketDraft="";ctl=null;ctlCsv="";annLive=null;renderAnnouncement();}registry.choice=result.registry_choice??registry.choice;registry.admin=result.registry_admin??false;registry.name=result.user_name??registry.name;if(command==="bugsMine"&&result.ok){tickets=result.tickets||[];ticketsLoaded=true;}if(result.ok&&result.ticket){threads[result.ticket.id]=result.ticket;const row=tickets.find(x=>x.id===result.ticket.id);if(row){const th=result.ticket.thread||[];row.status=result.ticket.status;row.count=th.length;row.last=th.length?th[th.length-1].from:row.last;}}state=result;if(["connect","resume"].includes(command))roleChecked=true;if(result.ok&&result.connected&&!roleChecked&&!demo&&command!=="disconnect"){roleChecked=true;setTimeout(()=>api("registryRole",{auto:true}),0);}if(command==="disconnect")roleChecked=false;if(result.ok||!["settings","purchase","reload","reloadQuick","reloadEdit","reloadDelete","purchaseEdit","purchaseDelete","bug","bugsMine","ticketThread","ticketSay"].includes(command)){dirty=false;if(["snapshot","bugsMine","ticketThread"].includes(command)){const sig=command+"|"+page+"|"+JSON.stringify(result);if(sig===lastSig[command])return result;lastSig[command]=sig;}render();}}
  if(!result.ok)notice(result.error||"Synchronisation interrompue. Réessaie avec Actualiser.");
  else if(["connect","resume"].includes(command)&&result.ok&&state.connected){page=registry.choice==="registered"?"dashboard":"privacy";closeMenu();render();setTimeout(()=>api("registryRole",{auto:true}),0);}
  else if(command==="bug"){notice("Ton ticket a bien été envoyé. Retrouve ses réponses ici.");page="tickets";ticketsLoaded=false;render();setTimeout(()=>{if(!busy&&page==="tickets")refreshTickets();},300);}
  else if(command==="reloadEdit"||command==="purchaseEdit"){editRow=null;page=command==="reloadEdit"?"history":"purchase";dirty=false;render();notice("Modification enregistrée.");}
  else if(command==="reloadDelete"||command==="purchaseDelete"){notice("Ligne supprimée.");}
  else if(command==="bugsMine")notice("Tes signalements sont à jour.");
  else if(command==="ticketSay")notice("Message envoyé à l’éditeur.");
  else if(command==="ticketResolve")notice("Ticket marqué comme résolu.");
  return result;
 }catch(e){notice(e.message);}finally{lock(false);}
}
function closeMenu(){$("drawer").classList.remove("open");$("scrim").hidden=true;}
function go(next){if(busy)return;if(dirty&&!confirm("Quitter ce formulaire sans enregistrer ?"))return;dirty=false;editRow=null;page=next;closeMenu();render();window.scrollTo(0,0);}
window.urb4nOpen=p=>{if(!["dashboard","updates"].includes(p)||page===p||busy)return;dirty=false;editRow=null;page=p;closeMenu();render();window.scrollTo(0,0);};
window.urb4nBack=()=>{if(busy)return;if($("drawer").classList.contains("open")){closeMenu();return;}if(page!=="dashboard"){go("dashboard");return;}if(state.pending){notice("Actualise pour confirmer le dernier enregistrement avant de quitter.");return;}if(window.Urb4nNative)api("exit");};
const NAVICO={"heart": "<path d=\"M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.5A4 4 0 0 1 19 10c0 5.6-7 10-7 10z\"/>", "dash": "<rect x=\"3\" y=\"4\" width=\"18\" height=\"12\" rx=\"2\"/><path d=\"M8 20h8M12 16v4M7 12l3-3 3 2 4-4\"/>", "fire": "<path d=\"M12 3c1 3 5 5 5 10a5 5 0 0 1-10 0c0-2 1-3 2-4 0 2 1 3 2 3 0-3-1-6 1-9z\"/>", "hist": "<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/>", "bag": "<path d=\"M6 8h12l1 12H5z\"/><path d=\"M9 8a3 3 0 0 1 6 0\"/>", "gear": "<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2\"/>", "note": "<path d=\"M6 3h9l4 4v14H6z\"/><path d=\"M9 11h7M9 15h7\"/>", "help": "<path d=\"M4 5h16v11H9l-5 4z\"/><path d=\"M8 9h8M8 12h5\"/>", "bug": "<path d=\"M12 3l10 18H2z\"/><path d=\"M12 10v5M12 18v.5\"/>", "users": "<circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M2 20c0-3.5 3-5.5 7-5.5s7 2 7 5.5M16 5a3.5 3.5 0 0 1 0 7M18 14.5c2.5.6 4 2.2 4 5.5\"/>", "user": "<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c0-4 4-6 8-6s8 2 8 6\"/>", "stats": "<path d=\"M4 20V10M10 20V4M16 20v-8M22 20H2\"/>", "down": "<path d=\"M12 3v12M7 10l5 5 5-5M5 20h14\"/>"};
const navIcon=k=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${NAVICO[k]}</svg>`;
const navGroups=[["Chauffage",[["dashboard","dash","Tableau de bord"],["reload","fire","Recharger le poêle"],["history","hist","Historique et bilans"],["purchase","bag","Achats de sacs"],["settings","gear","Paramètres"]]],["Aide",[["patch","note","Patch notes"],["tickets","help","Contact support"],["donate","heart","Soutenir le projet"]]],["Compte et application",[["adminctl","stats","Administration"],["privacy","user","Utilisateur"]]]];
$("side-nav").innerHTML=navGroups.map(([group,items])=>`<h4 class="nav-title">${group}</h4><div class="nav-group">${items.map(([key,icon,label])=>`<button data-page="${key}">${navIcon(icon)}<span>${label}</span></button>`).join("")}</div>`).join("");
$("menu-toggle").onclick=()=>{$("drawer").classList.add("open");$("scrim").hidden=false;};$("menu-close").onclick=closeMenu;$("scrim").onclick=closeMenu;
$("refresh").onclick=()=>state.connected?api("refresh"):go("connect");
document.addEventListener("click",event=>{const route=event.target.closest("[data-page]");if(route){if(route.dataset.page==="disconnect"){if(confirm("Déconnecter ce téléphone ? Tes données restent sur ton compte URB4N et sur tes autres appareils.")){demo=false;api("disconnect");closeMenu();}}else go(route.dataset.page);}const fuel=event.target.closest("[data-fuel]");if(fuel&&fuel.dataset.fuel!==state.fuel){if(dirty&&!confirm("Changer de suivi sans enregistrer le formulaire ?"))return;api("fuel",{fuel:fuel.dataset.fuel});}});
function title(text,sub){return `<h1>${text}</h1><p class="muted">${sub}</p>`;}
function option(values,sel){return values.map(value=>`<option value="${esc(value)}"${value===sel?" selected":""}>${esc(value)}</option>`).join("");}
function recordHtml(r,act){return `<div class="record"><div class="record-head"><strong>${esc(r.date)} · ${esc(r.hour)}</strong><span class="amount">${n(r.kg,2)} kg</span></div><p>${esc(r.fuel)} · ${esc(r.calibre)}</p><div class="record-head"><span><strong>Durée de chauffe :</strong> ${esc(r.duration)}</span><span>${money(r.cost)}</span></div>${act&&r.editable?`<div class="row-actions"><button type="button" class="secondary" data-edit-reload="${r.index}">Modifier</button><button type="button" class="danger" data-del-reload="${r.index}">Supprimer</button></div>`:""}</div>`;}
function record(r){return recordHtml(r,false);}
function recordA(r){return recordHtml(r,true);}
function isoOf(r){const d=String(r.date||"").split("/");return d.length===3?d[2]+"-"+d[1]+"-"+d[0]+"T"+r.hour:"";}
const GOAL_DAYS=120;
function ringSvg(outer,inner,days){const arc=(r,p)=>{const c=2*Math.PI*r;return `stroke-dasharray="${(Math.max(0,Math.min(1,p))*c).toFixed(1)} ${c.toFixed(1)}"`;};const hot=inner>=0.9;
 return `<svg class="ring2" viewBox="0 0 140 140" role="img" aria-label="Autonomie ${esc(days)} jours"><defs><linearGradient id="gA" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#78b60a"/><stop offset="1" stop-color="#b0f028"/></linearGradient><linearGradient id="gB" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${hot?"#c87828":"#5a8fe6"}"/><stop offset="1" stop-color="${hot?"#f7a949":"#82beff"}"/></linearGradient></defs><g transform="rotate(-90 70 70)" fill="none" stroke-linecap="round" stroke-width="11"><circle cx="70" cy="70" r="58" stroke="#222a25"/><circle cx="70" cy="70" r="58" stroke="url(#gA)" ${arc(58,outer)}/><circle cx="70" cy="70" r="40" stroke="#222a25"/>${inner>0?`<circle cx="70" cy="70" r="40" stroke="url(#gB)" ${arc(40,inner)}/>`:""}</g><text x="70" y="72" text-anchor="middle" class="ring-n">${esc(days)}</text><text x="70" y="90" text-anchor="middle" class="ring-s">jours</text></svg>`;}
let lastPlan="";
function planChargeAlert(){try{if(!window.Urb4nNative||!window.Urb4nNative.planAlert)return;const c=state.charge;const key=c?c.key:"";const at=c?Date.now()+Math.max(0,c.alert_in_min)*60000:0;const text=c?"Charge en cours : durée habituelle environ "+c.expected_text+".":"";const sig=key+"|"+Math.round(at/60000)+"|"+text;if(sig===lastPlan)return;lastPlan=sig;window.Urb4nNative.planAlert(key,String(at),text);}catch(e){}}
let weatherInfo=null,weatherAt=0,weatherTry=0,weatherBusy=false;try{const wx=JSON.parse(localStorage.getItem("urb4n.wx")||"null");if(wx&&wx.info&&wx.city&&wx.city===(localStorage.getItem("urb4n.city")||"").trim()){weatherInfo=wx.info;weatherAt=wx.at||0;}}catch(e){}
function cityName(){try{return(localStorage.getItem("urb4n.city")||"").trim();}catch(e){return"";}}
function setCityName(v){try{localStorage.setItem("urb4n.city",v);localStorage.removeItem("urb4n.geo");localStorage.removeItem("urb4n.wx");}catch(e){}weatherInfo=null;weatherAt=0;}
function maybeWeather(){try{if(!state.connected||demo||busy||weatherBusy)return;const c=cityName();if(!c)return;if(weatherInfo&&Date.now()-weatherAt<1800000)return;if(Date.now()-weatherTry<300000)return;weatherTry=Date.now();let g=null;try{g=JSON.parse(localStorage.getItem("urb4n.geo")||"null");}catch(e){}weatherBusy=true;api("weather",g&&g.typed===c?{city:c,lat:String(g.lat),lon:String(g.lon)}:{city:c});}catch(e){weatherBusy=false;}}
const dayName=(iso,i)=>i===0?"Auj.":i===1?"Demain":new Date(iso+"T12:00:00").toLocaleDateString("fr-BE",{weekday:"short"});
function weatherHtml(){const w=weatherInfo;if(!w)return"";const days=(w.days||[]).slice(0,4).map((d,i)=>`<span style="display:inline-block;margin:0 14px 4px 0"><b>${esc(dayName(d.date,i))}</b> ${Math.round(d.min)}° / ${Math.round(d.max)}°</span>`).join("");const l=w.link;const link=l?(l.pct>=5?`Les jours de gel (moins de ${l.below} °C), tu brûles environ <b>${n(l.cold_rate)} kg/jour</b> contre ${n(l.mild_rate)} kg/jour quand il fait plus doux : <b>${Math.round(l.pct)} % de plus</b> (d’après ${l.cold_n+l.mild_n} de tes charges).`:`Dans tes données, la température change peu ta consommation (${n(l.cold_rate)} kg/jour par temps froid, ${n(l.mild_rate)} kg/jour par temps doux).`):`<span class="muted">Pas encore assez de charges terminées pour relier la météo à ta consommation.</span>`;return `<section class="card"><h2>Météo · ${esc(w.city)}</h2><p><b style="font-size:1.4em">${Math.round(w.now)} °C</b> en ce moment</p><p>${days}</p><p>${link}</p></section>`;}
function stockDays(){try{const v=localStorage.getItem("urb4n.stockDays");if(v===null)return 7;const x=Number(v);return Number.isFinite(x)&&x>=0?x:7;}catch(e){return 7;}}
function setStockDays(v){try{localStorage.setItem("urb4n.stockDays",String(v));}catch(e){}}
function stockLow(){const d=stockDays(),v=(state.data||{}).view||{};return d>0&&v.Valid&&(state.connected||demo)&&Number(state.days)<=d&&n(v.Stock)!=="0,0"?d:0;}
function stockLowHtml(){const d=stockLow();return d?`<div class="charge-alert"><strong>Stock bas</strong> : il te reste environ ${state.days} jour${state.days>1?"s":""} de chauffage (rappel réglé à ${d} jours). Pense à acheter des sacs.</div>`:"";}
function planStockAlert(){try{if(!window.Urb4nNative||!window.Urb4nNative.planStockAlert)return;const d=stockDays(),v=(state.data||{}).view||{},daily=Number(v.Daily),stock=Number(v.Stock);let key="",at=0,text="";if(d>0&&v.Valid&&daily>0&&stock>0){const left=stock/daily;key="stock|"+d+"|"+Math.round(stock);at=Date.now()+Math.max(0,(left-d))*86400000;text="Il te reste environ "+d+" jours de chauffage : pense à acheter des sacs.";}const sig=key+"|"+Math.round(at/60000);if(sig===lastStockPlan)return;lastStockPlan=sig;window.Urb4nNative.planStockAlert(key,String(Math.round(at)),text);}catch(e){}}
let lastStockPlan="";
function quickHtml(){const q=state.quick;if(!q||!(state.connected||demo))return"";const what=state.fuel==="pellets"?n(q.kg)+" kg":esc(q.fraction||"");return `<section class="card"><button class="secondary full" data-quick="1">↻ Recharger comme la dernière fois</button><p class="muted">${esc(q.fuel)} · ${esc(q.calibre)}${what?" · "+what:""}, à l’heure actuelle.</p></section>`;}
function forecastHtml(){const f=state.forecast;if(!f)return"";const body=f.bags>0?`Il te manque environ <b>${n(f.missing_kg,0)} kg</b> : <b>${f.bags} sac${f.bags>1?"s":""}</b> de ${n(f.bag_kg,0)} kg, soit environ <b>${money(f.cost)}</b>.`:"Ton stock actuel couvre la fin de l’hiver.";return `<section class="card"><h2>Prévision de l’hiver</h2><p>D’ici le ${esc(f.end_date)} (${f.days} jours), avec ta consommation actuelle, il te faut environ ${n(f.need_kg,0)} kg. Tu as ${n(f.stock_kg,0)} kg en stock.</p><p>${body}</p><p class="muted">Estimation basée sur ta consommation moyenne et le prix de tes derniers achats.</p></section>`;}
const hoursText=h=>{const m=Math.round(h*60);return Math.floor(m/60)+" h "+String(m%60).padStart(2,"0");};
function compareHtml(){const c=state.compare;if(!c||!c.length)return"";return `<section class="card"><h2>Comparaison des combustibles</h2><p class="muted">Sur tes charges terminées, du moins cher au plus cher par jour.</p>${c.map((r,i)=>`<div class="record-head" style="padding:6px 0;border-top:${i?"0.5px solid rgba(255,255,255,.15)":"0"}"><span><b>${esc(r.fuel)}</b><br><small>${r.charges} charge${r.charges>1?"s":""} · ${hoursText(r.avg_hours)} en moyenne</small></span><span style="text-align:right"><b>${money(r.cost_per_day)}/j</b><br><small>${n(r.kg_per_day)} kg/j</small></span></div>`).join("")}</section>`;}
function dashboard(){
 const d=state.data||{},v=d.view||{},days=state.days||0,valid=!!v.Valid,kg=valid?n(v.Stock):"—",ch=state.charge||null,alerting=!!ch&&ch.ratio>=0.9;
 return title("Tableau de bord",`Ton suivi ${state.fuel}, synchronisé avec ton compte URB4N.`)+`<div class="card hero-card${alerting?" alerting":""}">${ringSvg(valid?Math.min(1,days/GOAL_DAYS):0,ch?ch.ratio:0,valid?days:"—")}<div class="hero-copy"><p class="eyebrow">Mon chauffage</p><h2>${valid?"Ton chauffage en un coup d’œil":"Connecte ton compte"}</h2><p><i class="dot lime"></i>Stock disponible : ${kg} kg${valid?` <b class="pct lime">${Math.round(Math.min(1,days/GOAL_DAYS)*100)} %</b>`:""}</p>${ch?`<p class="${alerting?"warn":""}"><i class="dot ${alerting?"orange":"blue"}"></i>Charge en cours depuis ${esc(ch.elapsed_text)} <b class="pct ${alerting?"orange":"blue"}">${Math.round(ch.ratio*100)} %</b></p>`:""}</div></div>${alerting?`<div class="charge-alert"><strong>À surveiller</strong> : ta charge approche de sa durée habituelle (${esc(ch.expected_text)}). Vérifie le poêle.</div>`:""}${stockLowHtml()}<div class="actions"><button class="primary" data-page="reload">♨ Recharger le poêle</button><button class="secondary" data-page="purchase"><svg class="ico bag" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6h12l2 4v10a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V10z"/><path d="M9 3l3 3 3-3"/><rect class="c1" x="8" y="12" width="3" height="3"/><rect class="c2" x="13" y="13" width="3" height="3"/><rect class="c3" x="10" y="17" width="3" height="3"/></svg> Ajouter des sacs</button></div>${quickHtml()}<div class="charge-status"><p><strong>Durée de chauffe de la dernière charge :</strong> ${state.reloads?.length?esc(state.reloads[0].duration):"Aucun rechargement enregistré"}</p><p>Autonomie calculée depuis ton stock et ta consommation moyenne (anneau : objectif de ${GOAL_DAYS} jours).</p>${ch&&!alerting?`<p>Durée attendue pour cette charge : environ ${esc(ch.expected_text)}, d’après tes dernières charges.</p>`:""}</div><div class="stats">${[["Stock restant",kg+" kg","Disponible","#a2df00"],["Sacs équivalents",valid?n(v.Stock/(d.bag_kg||25)):"—",`Sacs de ${n(d.bag_kg||25)} kg`,"#65aaff"],["Consommation",valid?n(v.Daily)+" kg/j":"—","Moyenne quotidienne","#ffae42"],["Coût moyen / jour",valid?money(state.dailyCost):"—","Selon tes achats","#30c69a"]].map(([label,value,caption,color])=>`<article class="card stat" style="--accent:${color}"><span class="label">${label}</span><strong>${value}</strong><small>${caption}</small></article>`).join("")}</div>${forecastHtml()}${weatherHtml()}${state.reloads?.length?chargeChart():'<section class="card"><h2>Dernières charges</h2><p class="empty">Aucun rechargement. Commence par ajouter ton stock dans Achats de sacs.</p></section>'}`;
}
function connect(){return title("Connexion Google","Retrouve le même suivi que sur ton PC Windows.")+`<section class="card"><div class="connect-icon">☁</div><h2>Ton chauffage te suit partout</h2><p class="muted">Connecte le même compte Google pour retrouver tes achats, rechargements et réglages Windows. Ton compte est créé à la première connexion et chaque utilisateur garde son propre espace privé.</p><button id="connect-google" class="primary full">Se connecter avec Google</button><p class="muted">Google sert uniquement à t’identifier. Tes données de chauffage sont enregistrées sur le serveur URB4N (avec une copie sur ce téléphone pour fonctionner sans Internet).</p><button id="demo" class="secondary full">Découvrir avec des données fictives</button><p></p><button data-page="tickets" class="secondary full">Contacter le support</button></section><p class="muted">La validation Google est encore en cours. Un avertissement et un plafond de connexions peuvent s’appliquer.</p><a class="link" href="https://urb4n-app.github.io/confidentialite.html">Confidentialité</a>`;}
const bagFrac={0.25:"¼",0.5:"½",0.75:"¾"};
function pelletBag(){const b=Number(state.data?.bag_kg);return b>0?b:15;}
function bagKgText(q){return String(Math.round(q*pelletBag()*100)/100).replace(",",".");}
function bagLabel(q){const w=Math.floor(q),f=Math.round((q-w)*100)/100,fr=bagFrac[f]||"";if(w===0)return f===0.5?"½ sac":fr+" de sac";if(!f)return w===1?"1 sac":w+" sacs";return (w===1?"1 sac ":w+" sacs ")+fr;}
function bagOptions(){let o="";for(let q=0.25;q<=4.001;q+=0.25){q=Math.round(q*100)/100;o+=`<option value="${q}"${q===1?" selected":""}>${bagLabel(q)} — ${String(Math.round(q*pelletBag()*100)/100).replace(".",",")} kg</option>`;}return o+'<option value="">Autre quantité</option>';}
function wireBags(){const sel=$("bags"),kg=$("kg");if(!sel||!kg)return;sel.addEventListener("change",()=>{if(sel.value)kg.value=bagKgText(Number(sel.value));});kg.addEventListener("input",()=>{const v=parseFloat(String(kg.value).replace(",","."));let found="";for(const o of sel.options){if(o.value&&Math.abs(Number(o.value)*pelletBag()-v)<0.005)found=o.value;}sel.value=found;});}
function reload(){const pellet=state.fuel==="pellets",ed=editRow&&editRow.k==="reload"?editRow.r:null;return title(ed?"Modifier un rechargement":"Nouveau rechargement",ed?"Corrige les champs puis enregistre : le stock et les durées de chauffe sont recalculés.":pellet?"Marque, calibre et quantité réellement versée.":"Enregistre la quantité de charbon réellement ajoutée.")+`<form id="reload-form" class="card"><label for="date">Date et heure (Belgique)</label><input id="date" name="date" type="datetime-local" value="${esc(ed?isoOf(ed):state.now||"")}" required><label for="fuel">${pellet?"Marque / combustible":"Combustible"}</label><select id="fuel" name="fuel">${option(state.fuels||[],ed&&ed.fuel)}</select><label for="calibre">Calibre</label><select id="calibre" name="calibre">${option(state.calibres||[],ed&&ed.calibre)}</select>${pellet?'<label for="bags">Quantité en sacs</label><select id="bags">'+bagOptions()+'</select><label for="kg">Ou poids exact versé (kg)</label><input id="kg" name="kg" inputmode="decimal" value="'+(ed?String(ed.kg).replace(".",","):bagKgText(1))+'" required>':'<label for="fraction">Quantité de charbonnière</label><select id="fraction" name="fraction">'+option(["1 charbonnière pleine","3/4 de charbonnière","1/2 charbonnière","1/4 de charbonnière"],ed&&ed.fraction)+"</select>"}<p class="muted">Utilise uniquement les combustibles et calibres compatibles avec la notice de ton poêle.</p><button class="primary full" type="submit">${ed?"Enregistrer la modification":"Valider ce rechargement"}</button>${ed?'<p></p><button type="button" id="cancel-edit" class="secondary full">Annuler la modification</button>':""}</form>${ed?"":'<section class="card sum" id="reload-sum">'+reloadSummaryHtml()+'</section>'}<section class="card"><h2>Mes derniers rechargements</h2>${(()=>{const all=chargeRows();return all.slice(-3).reverse().map(x=>chargeCard(x,all,true)).join("")||'<p class="empty">Aucun rechargement enregistré.</p>';})()}</section>`;}
function bagChoices(){const pellet=state.fuel==="pellets",list=pellet?[15]:[10,25],current=Number(state.data?.bag_kg),chosen=list.includes(current)?current:list[list.length-1];return list.map(v=>`<option value="${v}"${v===chosen?" selected":""}>${v} kg</option>`).join("");}
function purchase(){const ep=editRow&&editRow.k==="purchase"?editRow.p:null;return title(ep?"Modifier un achat":"Achats de sacs",ep?"Corrige le nombre de sacs ou le montant payé : le stock est recalculé.":`Ajoute un achat de ${state.fuel} à ton stock.`)+`<form id="purchase-form" class="card"><input type="hidden" name="priceMode" id="priceMode" value="total"><label for="bags">Nombre de sacs</label><input id="bags" name="bags" type="number" min="1" max="1000" value="${ep?ep.bags:1}" required><label for="unit">Prix d’un sac (€)</label><input id="unit" name="unit" inputmode="decimal"><label for="paid">Total du ticket (€)</label><input id="paid" name="paid" inputmode="decimal" value="${ep?String(ep.paid).replace(".",","):""}" required>${ep?"":`<label for="bagkg">Poids d’un sac</label><select id="bagkg" name="bagkg">${bagChoices()}</select>`}<p class="muted">Saisis le prix du sac ou le total payé : l’autre est calculé automatiquement. Le prix moyen est actualisé automatiquement.</p><button class="primary full" type="submit">${ep?"Enregistrer la modification":"Ajouter au stock"}</button>${ep?'<p></p><button type="button" id="cancel-edit" class="secondary full">Annuler la modification</button>':""}</form>${ep?"":'<section class="card sum" id="receipt">'+purchaseReceiptHtml()+'</section>'}<section class="card"><h2>Mes achats</h2>${purchaseCards()}</section>`;}
function history(){return title("Historique et bilans","Ton charbon et tes pellets restent séparés.")+`<div class="tabs"><button data-history="loads" class="${historyMode==="loads"?"selected":""}">Rechargements</button><button data-history="days" class="${historyMode==="days"?"selected":""}">Par jour</button><button data-history="months" class="${historyMode==="months"?"selected":""}">Par mois</button></div>${historyMode==="loads"?histLoads()+compareHtml():historyMode==="days"?histDays():histMonths()}`;}
// ---- Pages reprises de Windows : rechargements, achats, historique ----
const DOW=["dimanche","lundi","mardi","mercredi","jeudi","vendredi","samedi"];
let histFilter="all";
function parseDT(r){const d=String(r.date||"").split("/");if(d.length!==3)return null;const h=String(r.hour||"00:00").split(":");return new Date(+d[2],+d[1]-1,+d[0],+h[0]||0,+h[1]||0);}
function hmText(m){m=Math.max(0,Math.round(m));if(m<60)return m+" min";const h=Math.floor(m/60),r=m%60;return r?h+" h "+String(r).padStart(2,"0"):h+" h";}
function dayWords(t,now){const a=new Date(t.getFullYear(),t.getMonth(),t.getDate()),b=new Date(now.getFullYear(),now.getMonth(),now.getDate()),k=Math.round((b-a)/864e5),hh=String(t.getHours()).padStart(2,"0")+":"+String(t.getMinutes()).padStart(2,"0");let w;if(k===0)w="Aujourd’hui";else if(k===1)w="Hier";else if(k>1&&k<7)w=DOW[t.getDay()][0].toUpperCase()+DOW[t.getDay()].slice(1);else w=t.toLocaleDateString("fr-BE");return w+" · "+hh;}
function chargeRows(){const now=new Date(),list=(state.reloads||[]).slice().reverse().map(r=>({r,t:parseDT(r)})).filter(x=>x.t);list.forEach((x,i)=>{const nx=list[i+1];x.open=!nx;x.min=Math.max(0,((nx?nx.t:now)-x.t)/60000);});return list;}
function avgOf(rows){const c=rows.filter(x=>!x.open);return c.length>1?c.reduce((a,x)=>a+x.min,0)/c.length:0;}
function chargeChart(){const rows=chargeRows().slice(-7);if(!rows.length)return"";const avg=avgOf(rows),mx=Math.max(1,avg,...rows.map(x=>x.min));
 const bars=rows.map(x=>`<div class="cb"><span class="cb-v">${hmText(x.min)}</span><i class="${x.open?"blue":avg&&x.min<avg*.75?"orange":"green"}" style="height:${Math.max(4,Math.round(x.min/mx*100))}px"></i></div>`).join("");
 const dates=rows.map(x=>`<small>${String(x.t.getDate()).padStart(2,"0")}/${String(x.t.getMonth()+1).padStart(2,"0")}</small>`).join("");
 const closed=rows.filter(x=>!x.open),long=closed.length?Math.max(...closed.map(x=>x.min)):0,short=closed.length?Math.min(...closed.map(x=>x.min)):0;
 return `<section class="card"><h2>Dernières charges</h2><div class="cplot">${avg?`<div class="cb-avg" style="bottom:${Math.round(avg/mx*100)}px"><span>moyenne ${hmText(avg)}</span></div>`:""}${bars}</div><div class="cdates">${dates}</div><div class="kpis"><div><small>Moyenne</small><b>${avg?hmText(avg):"—"}</b></div><div><small>Plus longue</small><b>${closed.length>1?hmText(long):"—"}</b></div><div><small>Plus courte</small><b>${closed.length>1?hmText(short):"—"}</b></div></div></section>`;}
function chargeCard(x,all,act){const r=x.r,avg=avgOf(all),mx=Math.max(1,...all.map(y=>y.min)),cls=x.open?"blue":avg&&x.min<avg*.75?"orange":"green";
 return `<div class="rcard"><div class="record-head"><strong>${esc(dayWords(x.t,new Date()))}</strong><span class="amount">${n(r.kg,2)} kg</span></div><p class="muted">${esc(r.fuel)} · ${esc(r.calibre)}</p><div class="rc-bar"><i class="${cls}" style="width:${Math.max(3,Math.round(x.min/mx*100))}%"></i></div><div class="record-head"><span>${x.open?"En cours · ":"Durée "}${hmText(x.min)}</span><span>${money(r.cost)}</span></div>${act&&r.editable?`<div class="row-actions"><button type="button" class="secondary" data-edit-reload="${r.index}">Modifier</button><button type="button" class="danger" data-del-reload="${r.index}">Supprimer</button></div>`:""}</div>`;}
function numOf(id){const e=$(id);return e?parseFloat(String(e.value).replace(",",".")):NaN;}
function reloadKg(){const d=state.data||{};if(state.fuel==="pellets")return numOf("kg");const net=Math.max(0,(d.bucket_full_kg||0)-(d.bucket_empty_kg||0)),f=$("fraction")?$("fraction").value:"";const q={"1 charbonnière pleine":1,"3/4 de charbonnière":.75,"1/2 charbonnière":.5,"1/4 de charbonnière":.25}[f];return q?net*q:NaN;}
function reloadDateProblem(){const e=$("date");if(!e||!e.value)return"";const t=new Date(e.value);return t.getTime()>Date.now()+60000?"La date du rechargement est dans le futur : choisis maintenant ou une date passée.":"";}
function reloadSummaryHtml(){const d=state.data||{},v=d.view||{},rows=chargeRows(),last=rows[rows.length-1],e=$("date"),t=e&&e.value?new Date(e.value):new Date(),kg=reloadKg(),exp=state.charge?state.charge.expected_min:0;
 const el=last?(t-last.t)/60000:null,future=reloadDateProblem(),short=!future&&el!==null&&exp>0&&el<exp*.75;
 const stock=Number(v.Stock)||0,after=Number.isFinite(kg)?Math.max(0,stock-kg):null,daily=Number(v.Daily)||0;
 const row=(a,b)=>`<div class="sum-row"><span>${a}</span><b>${b}</b></div>`;
 return `<h2>Ce qui va se passer</h2>${row("Charge en cours",last&&el>=0?"clôturée après "+hmText(el):"—")}${row("Durée attendue",exp>0?"environ "+hmText(exp):"—")}${row("Nouvelle charge",Number.isFinite(kg)?n(kg,2)+" kg":"—")}${row("Stock",after!==null&&v.Valid?n(stock)+" → "+n(after)+" kg":"—")}${row("Autonomie",after!==null&&daily>0?Math.floor(stock/daily)+" → "+Math.floor(after/daily)+" jours":"—")}${future?`<div class="sum-warn">${esc(future)}</div>`:""}${short?`<div class="sum-warn">La charge en cours a tenu ${hmText(el)} : c’est plus court que d’habitude (environ ${hmText(exp)}). Vérifie l’heure si ce n’est pas normal.</div>`:""}`;}
function updateReloadSummary(){const b=$("reload-sum");if(b)b.innerHTML=reloadSummaryHtml();}
function purchaseReceiptHtml(){const d=state.data||{},v=d.view||{},bags=numOf("bags"),paid=numOf("paid"),bagkg=$("bagkg")?numOf("bagkg"):(d.bag_kg||25),pellet=state.fuel==="pellets",ok=bags>0&&paid>=0&&Number.isFinite(paid);
 const unit=ok?paid/bags:0,add=ok?bags*bagkg:0,stock=Number(v.Stock)||0,daily=Number(v.Daily)||0;
 const row=(a,b)=>`<div class="sum-row"><span>${a}</span><b>${b}</b></div>`;
 return `<h2>— ACHAT DE ${pellet?"PELLETS":"CHARBON"} —</h2>${row(ok?bags+" × "+money(unit):"—",ok?money(paid):"—")}${row("Poids ajouté",ok?n(add)+" kg":"—")}${row("Stock",ok&&v.Valid?n(stock)+" → "+n(stock+add)+" kg":"—")}${row("Autonomie",ok&&daily>0?Math.floor(stock/daily)+" → "+Math.floor((stock+add)/daily)+" jours":"—")}`;}
function updateReceipt(){const b=$("receipt");if(b)b.innerHTML=purchaseReceiptHtml();}
function purchaseCards(){const list=(state.data?.purchases||[]).map((p,i)=>({p,i}));const unit=x=>x.p.bags>0?x.p.paid/x.p.bags:0;
 return list.slice().reverse().map(x=>{const prev=list[x.i-1],u=unit(x),pu=prev?unit(prev):0;let trend="";if(prev&&pu>0){const pc=(u-pu)/pu*100;if(Math.abs(pc)>=0.5)trend=`<span class="trend ${pc>0?"up":"down"}">${pc>0?"▲":"▼"} ${n(Math.abs(pc))} %</span>`;else trend='<span class="trend">= stable</span>';}
  return `<div class="rcard"><div class="record-head"><strong>${esc(x.p.date)}</strong><span class="amount">${money(x.p.paid)}</span></div><p>${x.p.bags} sacs · ${n(x.p.kg)} kg</p><div class="record-head"><span>${money(u)} / sac</span>${trend}</div>${x.i>=(state.data?.imported_purchases||0)?`<div class="row-actions"><button type="button" class="secondary" data-edit-purchase="${x.i}">Modifier</button><button type="button" class="danger" data-del-purchase="${x.i}">Supprimer</button></div>`:""}</div>`;}).join("")||'<p class="empty">Aucun achat enregistré.</p>';}
function histRows(){const all=chargeRows(),now=new Date();return all.filter(x=>histFilter==="all"||(histFilter==="month"&&x.t.getMonth()===now.getMonth()&&x.t.getFullYear()===now.getFullYear())||(histFilter==="30"&&now-x.t<=30*864e5)||(histFilter.startsWith("f:")&&x.r.fuel===histFilter.slice(2)));}
function histLoads(){const all=chargeRows(),rows=histRows(),avg=avgOf(rows),cost=rows.reduce((a,x)=>a+(x.r.cost||0),0),fuels=[...new Set(all.map(x=>x.r.fuel))];
 const chips=[["all","Tous"],["month","Ce mois"],["30","30 jours"],...fuels.map(f=>["f:"+f,f])].map(([k,l])=>`<button type="button" class="chip${histFilter===k?" on":""}" data-hist-filter="${esc(k)}">${esc(l)}</button>`).join("");
 return `<div class="kpis"><div><small>Rechargements</small><b>${rows.length}</b></div><div><small>Durée moyenne</small><b>${avg?hmText(avg):"—"}</b></div><div><small>Dépense</small><b>${money(cost)}</b></div></div><div class="chips">${chips}</div><section class="card">${rows.slice().reverse().map(x=>chargeCard(x,all,false)).join("")||'<p class="empty">Aucun rechargement pour ce filtre.</p>'}</section>`;}
const FRM=["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
function histDays(){const list=(state.daily||[]).slice(-14),mx=Math.max(0.01,...list.map(t=>t.Cost)),tot=list.reduce((a,t)=>a+t.Cost,0),kg=list.reduce((a,t)=>a+t.Kg,0);
 const bars=list.map(t=>`<div class="cb"><span class="cb-v">${n(t.Cost,2)}</span><i class="green" style="height:${Math.max(4,Math.round(t.Cost/mx*100))}px"></i></div>`).join(""),dates=list.map(t=>`<small>${esc(t.Key.slice(8,10))}/${esc(t.Key.slice(5,7))}</small>`).join("");
 return `<div class="kpis"><div><small>14 derniers jours</small><b>${money(tot)}</b></div><div><small>Charbon / pellets</small><b>${n(kg)} kg</b></div></div>${list.length?`<section class="card"><h2>Montants par jour</h2><div class="cplot small">${bars}</div><div class="cdates">${dates}</div></section>`:""}<section class="card">${(state.daily||[]).slice().reverse().map(t=>`<div class="record"><div class="record-head"><strong>${esc(t.Key.split("-").reverse().join("/"))}</strong><span>${money(t.Cost)}</span></div><p>${n(t.Kg)} kg · ${t.Count} rechargement(s)</p></div>`).join("")||'<p class="empty">Aucune donnée.</p>'}</section>`;}
function histMonths(){const list=(state.monthly||[]).slice(),now=new Date(),cur=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0");
 return list.slice().reverse().map((t,i,a)=>{const prev=a[i+1],y=+t.Key.slice(0,4),m=+t.Key.slice(5,7)-1;let tr="";if(prev&&prev.Cost>0){const pc=(t.Cost-prev.Cost)/prev.Cost*100;tr=`<span class="trend ${pc>0?"up":"down"}">${pc>0?"▲":"▼"} ${n(Math.abs(pc),0)} % vs ${FRM[+prev.Key.slice(5,7)-1]}</span>`;}
  let proj="";if(t.Key===cur){const day=now.getDate(),dim=new Date(y,m+1,0).getDate();if(day>=3)proj=`<p class="muted">Projection fin de mois : ${money(t.Cost/day*dim)}</p>`;}
  return `<section class="card"><div class="record-head"><h2>${esc(FRM[m])} ${y}</h2>${tr}</div><div class="kpis"><div><small>Dépense</small><b>${money(t.Cost)}</b></div><div><small>Quantité</small><b>${n(t.Kg)} kg</b></div><div><small>Charges</small><b>${t.Count}</b></div></div>${proj}</section>`;}).join("")||'<section class="card"><p class="empty">Aucune donnée.</p></section>';}
function patchKind(t){const l=t.toLowerCase(),has=(...w)=>w.some(x=>l.includes(x));if(has("est retiré","est retirée","se demande à l","disparaît","supprimé"))return 3;if(l.startsWith("correction")||has("correctement","plus de clignotement","ne se ferment plus","corrigé"))return 1;if(has("remonte","déplacé","est maintenant","nouvelle présentation","plus claire","plus lisible"))return 2;return 0;}
function settings(){const d=state.data||{},pellet=state.fuel==="pellets";return title("Paramètres du chauffage","Adapte l’application à ton matériel.")+(pellet?`<section class="card"><p class="muted">Les sacs de pellets font 15 kg. Le poids se choisit à chaque achat.</p></section>`:`<form id="settings-form" class="card"><div class="form-grid"><div><label for="empty">Charbonnière vide (kg)</label><input id="empty" name="empty" inputmode="decimal" value="${esc(d.bucket_empty_kg??"")}" required></div><div><label for="full">Charbonnière pleine (kg)</label><input id="full" name="full" inputmode="decimal" value="${esc(d.bucket_full_kg??"")}" required></div></div><p class="net" id="net">Charbon net : à calculer</p><p class="muted">Le poids d’un sac se choisit à chaque achat. Le prix est calculé depuis tes achats. Les anciennes charges restent inchangées.</p><button type="submit" class="primary full">Enregistrer mes réglages</button></form>`)+`<section class="card"><h2>Météo</h2><label for="city">Ta ville</label><input id="city" value="${esc(cityName())}" placeholder="Bruxelles" maxlength="80"><p></p><button type="button" id="save-city" class="secondary full">Enregistrer la ville</button><p class="muted">Sert à afficher la température et à relier le froid à ta consommation. Seul le nom de ta ville est envoyé au service Open-Meteo.</p></section>`+`<section class="card"><h2>Rappel de fin de stock</h2><label for="stock-days">Me prévenir quand il reste</label><select id="stock-days">${[[0,"Jamais"],[3,"3 jours"],[5,"5 jours"],[7,"7 jours"],[10,"10 jours"],[14,"14 jours"]].map(([v,t])=>`<option value="${v}"${v===stockDays()?" selected":""}>${t}</option>`).join("")}</select><p class="muted">Un message s’affiche sur l’accueil, et une notification est envoyée sur Android.</p></section>`+`<section class="card"><h2>Compte</h2><button data-page="disconnect" class="secondary full">Me déconnecter</button></section><section class="card"><h2>Gérer mes données</h2><p class="muted">Ces actions concernent aussi le même compte sur Windows.</p><button data-destructive="resetCoal" class="danger full">Réinitialiser les données charbon</button><p></p><button data-destructive="resetPellets" class="danger full">Réinitialiser les données pellets</button></section>`;}
