 `<section class="card"><h2>Annonce à tous les utilisateurs</h2><p class="muted">${ctl&&ctl.announcement?(ctl.announcement.active===false?"Programmée le "+esc(new Date(ctl.announcement.starts).toLocaleString("fr-BE",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"}))+" · ":"En cours : ")+esc(ctl.announcement.text)+annWhere(ctl.announcement):"Aucune annonce en cours."}</p><label for="ctl-ann">Texte</label><input id="ctl-ann" maxlength="300" autocomplete="off"><div class="form-grid"><div><label for="ctl-level">Type</label><select id="ctl-level"><option value="info">Information</option><option value="warning">Important</option><option value="urgent">Urgent</option></select></div><div><label for="ctl-days">Durée</label><select id="ctl-days"><option value="1">1 jour</option><option value="3">3 jours</option><option value="7" selected>7 jours</option><option value="14">14 jours</option><option value="30">30 jours</option></select></div></div><div class="form-grid"><div><label for="ctl-start">Début</label><select id="ctl-start">${START_CHOICES.map((c,i)=>`<option value="${i}">${c}</option>`).join("")}</select></div><div><label for="ctl-target">Pour qui</label><select id="ctl-target">${TARGET_CHOICES.map(([v,c])=>`<option value="${v}">${c}</option>`).join("")}</select></div></div><div class="actions"><button id="ctl-announce" class="primary">Publier l’annonce</button><button id="ctl-clear" class="secondary">Retirer l’annonce</button></div></section>`+
 `<section class="card"><h2>Export CSV</h2><div class="actions"><button id="ctl-exp-users" class="secondary">Comptes</button><button id="ctl-exp-bugs" class="secondary">Bugs</button></div>${ctlCsv?`<label for="ctl-csv">${esc(ctlCsvName)}</label><textarea id="ctl-csv" readonly>${esc(ctlCsv)}</textarea><button id="ctl-copy" class="primary full">Copier le texte</button>`:""}</section>`;
