function versionsHtml(s,users){
 const rows=Object.entries(s.versions||{}).map(([k,n])=>{const i=k.indexOf(" ");return{p:k.slice(0,i),v:k.slice(i+1),n};}).sort((a,b)=>b.n-a.n||(a.p+a.v).localeCompare(b.p+b.v));
 if(!rows.length)return`<p class="muted">Versions : aucune connexion récente avec numéro de version.</p>`;
 const best={};for(const r of rows)if(!best[r.p]||verLess(best[r.p],r.v))best[r.p]=r.v;
 const name=p=>({windows:"Windows",android:"Android",web:"Web / iPhone"}[p]||p);
 return`<p class="muted" style="margin-bottom:4px">Versions installées</p>`+rows.slice(0,6).map(r=>{const old=verLess(r.v,best[r.p]);return`<div class="record-head" style="padding:3px 0;font-size:13px${old?";color:#f7a949":""}"><span>${esc(name(r.p))} ${esc(r.v)}${old?" · ancienne":""}</span><span>${r.n} compte(s)</span></div>`;}).join("")+(rows.length>6?`<p class="muted">… et ${rows.length-6} autre(s) version(s)</p>`:"");
}
